def _build_component_06():
    def solve(data):
        packages = data["packages"]
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        initial = {name: [(bounds[0], bounds[1])]
                   for name, bounds in data.get("roots", {}).items()}
        best_vector = None
        best = None
        names_desc = sorted(packages, reverse=True)

        def active_deps(row):
            return [dep for dep in row.get("deps", [])
                    if not dep.get("feature") or dep["feature"] in features]

        def permitted(name, version, reqs):
            if any(not low <= version <= high for low, high in reqs.get(name, [])):
                return False
            if version in blocked.get(name, []):
                return False
            if name in pins and version != pins[name]:
                return False
            return True

        def is_acyclic(edges):
            done, active = set(), set()

            def visit(name):
                if name in active:
                    return False
                if name in done:
                    return True
                active.add(name)
                for other in edges.get(name, []):
                    if not visit(other):
                        return False
                active.remove(name)
                done.add(name)
                return True

            return all(visit(name) for name in edges)

        def search(chosen, reqs, edges):
            nonlocal best, best_vector
            if any(not permitted(name, version, reqs)
                   for name, version in chosen.items()):
                return
            unresolved = [name for name in reqs if name not in chosen]
            if not unresolved:
                if not is_acyclic(edges):
                    return
                vector = tuple(chosen.get(name, -1) for name in names_desc)
                if best_vector is None or vector > best_vector:
                    best_vector = vector
                    best = dict(chosen)
                return

            name = min(unresolved)
            candidates = [row for row in packages.get(name, [])
                          if permitted(name, row["version"], reqs)]
            for row in sorted(candidates, key=lambda item: item["version"], reverse=True):
                version = row["version"]
                next_chosen = dict(chosen)
                next_chosen[name] = version
                next_reqs = {key: list(value) for key, value in reqs.items()}
                next_edges = {key: list(value) for key, value in edges.items()}
                deps = active_deps(row)
                next_edges[name] = [dep["name"] for dep in deps]
                for dep in deps:
                    next_reqs.setdefault(dep["name"], []).append(
                        (dep["min"], dep["max"]))
                search(next_chosen, next_reqs, next_edges)

        search({}, initial, {})
        if best is None:
            return {"error": "unsatisfiable"}
        return {"versions": best}
    return solve


def _build_component_07():
    from itertools import combinations
    import heapq

    def solve(data):
        jobs = [job for job in data["jobs"]
                if job["id"] not in data.get("blocked", [])]
        k = data["k"]
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None

        for subset in combinations(jobs, k):
            ids = {job["id"] for job in subset}
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in subset:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue

            active = []
            valid = True
            for job in sorted(subset, key=lambda row: (row["start"], row["end"])):
                while active and active[0] <= job["start"]:
                    heapq.heappop(active)
                heapq.heappush(active, job["end"])
                if len(active) > 2:
                    valid = False
                    break
            if not valid:
                continue

            value = sum(job["value"] for job in subset)
            sorted_ids = sorted(ids)
            if (best_value is None or value > best_value or
                    (value == best_value and sorted_ids > best_ids)):
                best_value, best_ids = value, sorted_ids

        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


def _build_component_08():
    import heapq

    def solve(data):
        required = data.get("required", [])
        indexes = {node: index for index, node in enumerate(required)}
        full = (1 << len(required)) - 1
        initial_mask = 0
        if data["source"] in indexes:
            initial_mask |= 1 << indexes[data["source"]]

        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        start_state = (data["source"], initial_mask, data["coupons"])
        distances = {start_state: data["start"]}
        queue = [(data["start"], data["source"], initial_mask, data["coupons"])]
        while queue:
            time, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if distances.get(state) != time:
                continue
            if node == data["target"] and mask == full:
                return {"arrival": time}

            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                for spent in (0, 1):
                    if spent and not remaining:
                        continue
                    duration = edge["duration"]
                    if spent:
                        duration = max(1, duration - edge.get("discount", 0))
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    next_node = edge["v"]
                    next_mask = mask
                    if next_node in indexes:
                        next_mask |= 1 << indexes[next_node]
                    next_remaining = remaining - spent
                    next_state = (next_node, next_mask, next_remaining)
                    if arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = arrival
                        heapq.heappush(queue, (arrival, next_node, next_mask,
                                              next_remaining))
        return {"arrival": None}
    return solve


